import {RECIPE_INGREDIENTS} from './measuring-recipes-content.mjs';
import {recipeScale} from './measuring-recipes-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

// Straight-sided picture vessels: ten equal intervals, eleven marks.
// Each SVG is self-contained; no shared IDs or external image resources.
export function recipeJugArt(amount,ingredient,{jar=false,label='Measuring jug'}={}){
 const scale=recipeScale(amount);if(!scale)return '';
 const item=RECIPE_INGREDIENTS.find(x=>x.id===ingredient),ink='#183f39',left=35,width=116,top=47,bottom=267,height=bottom-top,y=bottom-height*scale.levelFraction;
 const marks=scale.ticks.map(t=>{const ty=bottom-height*t.levelFraction;return `<path d="M${left+width-(t.major?24:13)} ${ty}H${left+width+7}" stroke="${ink}" stroke-width="${t.major?2:1.5}"/>${t.major?`<text x="${left+width+14}" y="${ty+7}" fill="${ink}" font-size="28">${t.label}</text>`:''}`;}).join('');
 const liquid=amount===0?'':`<rect x="${left}" y="${y}" width="${width}" height="${bottom-y}" fill="${item?.colour||'#729faf'}"/>${item?.pattern==='stripes'?Array.from({length:Math.ceil((bottom-y)/12)},(_,i)=>{const py=Math.min(bottom-2,y+5+i*12);return `<path d="M${left+2} ${py}H${left+width-2}" stroke="#705a24" stroke-opacity=".6" stroke-width="2"/>`;}).join(''):Array.from({length:Math.ceil((bottom-y)/16)},(_,i)=>Array.from({length:5},(_,j)=>`<circle cx="${left+9+j*23}" cy="${Math.min(bottom-3,y+7+i*16)}" r="2" fill="#234d60" fill-opacity=".65"/>`).join('')).join('')}<path d="M${left} ${y}H${left+width}" stroke="${ink}" stroke-width="2"/>`;
 return `<svg class="mr-vessel-art ${jar?'mr-jar-art':''}" viewBox="0 0 230 300" role="img" aria-label="${esc(label)}: capacity 500 millilitres; contains ${amount} millilitres${item?` of ${esc(item.name)}`:''}. Eleven marks form ten equal 50 millilitre intervals."><text x="115" y="20" text-anchor="middle" fill="${ink}" font-size="24">Capacity 500 mL</text>${!jar?'<path d="M33 75H20Q5 75 5 115v60q0 35 15 35h13" fill="none" stroke="#729584" stroke-width="8"/>':''}<rect x="${left}" y="${top}" width="${width}" height="${height}" fill="#f2f7ef"/>${liquid}<path d="M${left} ${top}V${bottom}H${left+width}V${top}" fill="none" stroke="${ink}" stroke-width="3"/>${jar?`<path d="M${left-3} ${top}H${left+width+3}" stroke="${ink}" stroke-width="4"/>`:`<path d="M${left} ${top}l-12-12h${width+12}l12 12" fill="none" stroke="${ink}" stroke-width="3"/>`}${marks}<text x="115" y="292" text-anchor="middle" fill="${ink}" font-size="24">mL · millilitres</text></svg>`;
}

export function recipeIntervalStrip(){return `<svg class="mr-interval-art" viewBox="0 0 520 82" role="img" aria-label="A supplied scale strip: ten equal spaces of 50 millilitres between eleven marks. Zero to 500 millilitres.">${Array.from({length:10},(_,i)=>`<rect x="${25+i*47}" y="12" width="47" height="25" fill="${i%2?'#c3d8db':'#e5ecda'}" stroke="#729584"/>`).join('')}${Array.from({length:11},(_,i)=>`<path d="M${25+i*47} 8V43" stroke="#183f39"/>${i%2===0?`<text x="${25+i*47}" y="63" text-anchor="middle" font-size="24" fill="#183f39">${i*50}</text>`:''}`).join('')}</svg>`;}

export function recipeIngredientMark(id){const item=RECIPE_INGREDIENTS.find(x=>x.id===id);return item?`<span class="mr-ingredient-mark mr-mark-${item.pattern}" aria-hidden="true">${item.pattern==='dots'?'•••':'///'}</span>`:'';}
